insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-wins-and-wobbles-ledger', 'Weekly Wins and Wobbles Ledger', 'worksheet'::resource_kind, 'The client logs one win and one wobble each day and what each taught them.', 'Use it to help a client notice progress alongside setbacks.', array['Adults', 'Teens']::text[], 'One week', 'Review the ledger together and look for patterns across days, not a score. Wobbles are information, so keep your tone curious. Ask which small win the client would like to repeat and plan one way to make it easier.', '[{"id": "f0", "type": "textarea", "label": "Monday win and wobble"}, {"id": "f1", "type": "textarea", "label": "Midweek win and wobble"}, {"id": "f2", "type": "textarea", "label": "Weekend win and wobble"}, {"id": "f3", "type": "textarea", "label": "What the wobbles had in common"}, {"id": "f4", "type": "textarea", "label": "One win I want to repeat"}]'::jsonb, array['self-monitoring', 'strengths', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('weekly-energy-give-and-take-planner', 'Weekly Energy Give and Take Planner', 'worksheet'::resource_kind, 'The client lists the week''s tasks and marks which give energy and which take it.', 'Use it to help a client plan a week around their energy.', array['Adults']::text[], '30 minutes', 'Have the client sort tasks into gives, takes and both, then place one restoring activity beside each draining one. Check that the plan is realistic rather than perfect, and adjust after a week.', '[{"id": "f0", "type": "textarea", "label": "Tasks that give me energy"}, {"id": "f1", "type": "textarea", "label": "Tasks that take my energy"}, {"id": "f2", "type": "textarea", "label": "What I can move, shorten or share"}, {"id": "f3", "type": "textarea", "label": "One restoring activity I will add"}]'::jsonb, array['planning', 'routines', 'stress']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('small-talk-starter-cards-worksheet', 'Small Talk Starter Cards Worksheet', 'worksheet'::resource_kind, 'The client drafts a few easy openers and follow-up questions for different settings.', 'Use it to help a client prepare low-pressure conversation starters.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick two settings the client actually faces. Let them draft openers in their own voice and rehearse aloud once. Keep the cards short enough to remember and note which one they will try first.', '[{"id": "f0", "type": "textarea", "label": "A setting where I want to chat"}, {"id": "f1", "type": "textarea", "label": "Openers that sound like me"}, {"id": "f2", "type": "textarea", "label": "Follow-up questions I could ask"}, {"id": "f3", "type": "textarea", "label": "The one I will try first"}]'::jsonb, array['social skills', 'communication', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('decision-pros-cons-and-values-grid', 'Decision Pros, Cons and Values Grid', 'worksheet'::resource_kind, 'The client weighs a choice by listing pros, cons and which values each one touches.', 'Use it to help a client make a choice that fits what matters to them.', array['Adults', 'Teens']::text[], '30 minutes', 'Work through one real decision. After the pros and cons, ask which values each side serves and which the client would be proud to act on. The grid supports their thinking; it does not choose for them.', '[{"id": "f0", "type": "textarea", "label": "The decision in front of me"}, {"id": "f1", "type": "textarea", "label": "Pros"}, {"id": "f2", "type": "textarea", "label": "Cons"}, {"id": "f3", "type": "textarea", "label": "Values each option touches"}, {"id": "f4", "type": "textarea", "label": "The next small step I will take"}]'::jsonb, array['decisions', 'values', 'problem solving']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('morning-and-evening-bookends-sheet', 'Morning and Evening Bookends Sheet', 'worksheet'::resource_kind, 'The client designs a short routine for the start and end of the day and tracks it.', 'Use it to help a client anchor the day with two small routines.', array['Adults', 'Teens']::text[], 'One week', 'Keep each bookend to three or four steps the client already half does. Review which steps stuck and which felt like a chore, then trim. Simple beats ambitious here.', '[{"id": "f0", "type": "textarea", "label": "My morning steps"}, {"id": "f1", "type": "textarea", "label": "My evening steps"}, {"id": "f2", "type": "textarea", "label": "What got in the way"}, {"id": "f3", "type": "textarea", "label": "What I will change next week"}]'::jsonb, array['routines', 'habits', 'self-monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('hot-thought-highlighter', 'Hot Thought Highlighter', 'cbt'::resource_kind, 'The client circles the most emotionally charged thought in a situation and works it.', 'Use it to help a client find the thought carrying the most feeling.', array['Adults', 'Teens']::text[], '25 minutes', 'After the client writes the situation and their thoughts, ask which one makes the feeling spike. Circle it and carry it into evidence for and against. Reviewing the hot thought together usually shows what a client believes at the core.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Thoughts that came up"}, {"id": "f2", "type": "textarea", "label": "The hot thought (the one with the most feeling)"}, {"id": "f3", "type": "textarea", "label": "Evidence for it"}, {"id": "f4", "type": "textarea", "label": "Evidence against it"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought"}]'::jsonb, array['core CBT', 'automatic thoughts', 'thought record']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-planner-page', 'Behavioral Experiment Planner Page', 'cbt'::resource_kind, 'The client turns a prediction into a small test and records what actually happened.', 'Use it to help a client check a prediction against real experience.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a prediction the client can safely test this week. Write it with a confidence rating, plan the test, then compare. The client''s own observations carry more weight than your reassurance.', '[{"id": "f0", "type": "textarea", "label": "My prediction"}, {"id": "f1", "type": "textarea", "label": "How sure I am (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "The experiment I will run"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I take from it"}]'::jsonb, array['behavioral experiment', 'core CBT', 'evidence']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('double-standard-letter', 'Double Standard Letter', 'cbt'::resource_kind, 'The client writes to themselves the way they would write to a friend in the same spot.', 'Use it to help a client notice the gap between how they treat others and themselves.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to describe a struggle, then write the note they would send a friend with it. Read it aloud together and notice the difference in tone. Keep the focus on kinder, balanced wording.', '[{"id": "f0", "type": "textarea", "label": "What I am being hard on myself about"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "Words from that note I could use for myself"}, {"id": "f3", "type": "textarea", "label": "How it feels to read it back"}]'::jsonb, array['self-criticism', 'self-compassion', 'core CBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('doing-and-feeling-connection-chart', 'Doing and Feeling Connection Chart', 'cbt'::resource_kind, 'The client rates mood alongside activities to see which parts of the day lift or lower it.', 'Use it to help a client see links between activities and mood.', array['Adults', 'Teens']::text[], 'One week', 'Have the client jot an activity and a 1 to 10 mood rating at a few points each day. Look for patterns together and let the client draw their own conclusions before you add yours.', '[{"id": "f0", "type": "textarea", "label": "What I did in the morning and how I felt"}, {"id": "f1", "type": "textarea", "label": "What I did in the afternoon and how I felt"}, {"id": "f2", "type": "textarea", "label": "What I did in the evening and how I felt"}, {"id": "f3", "type": "textarea", "label": "Patterns I notice"}, {"id": "f4", "type": "textarea", "label": "One change I will try"}]'::jsonb, array['behavioral activation', 'monitoring', 'self-monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('pie-chart-of-responsibility', 'Pie Chart of Responsibility', 'cbt'::resource_kind, 'The client divides up who and what contributed to an outcome they blame themselves for.', 'Use it to help a client share responsibility more accurately.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an event where the client takes all the blame. Have them list every factor first, then slice the pie, putting themselves last. Ask what they notice and keep room for accountability that is real.', '[{"id": "f0", "type": "textarea", "label": "The event"}, {"id": "f1", "type": "textarea", "label": "Everything that played a part"}, {"id": "f2", "type": "textarea", "label": "My honest share"}, {"id": "f3", "type": "textarea", "label": "What I notice looking at the pie"}]'::jsonb, array['guilt', 'thinking traps', 'core CBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('loud-passengers-driving-rehearsal', 'Loud Passengers Driving Rehearsal', 'act'::resource_kind, 'The client names difficult thoughts as passengers and keeps driving toward a chosen direction.', 'Use it to help a client act on values with hard thoughts along for the ride.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk the metaphor slowly: the driver, the bus, the loud passengers. Let the client name their passengers and pick where the bus is heading. Practice a brief moment of letting them talk while still driving.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive"}, {"id": "f1", "type": "textarea", "label": "The loud passengers"}, {"id": "f2", "type": "textarea", "label": "What they tell me to do"}, {"id": "f3", "type": "textarea", "label": "What I do while they talk"}, {"id": "f4", "type": "textarea", "label": "One action I will take this week"}]'::jsonb, array['core ACT', 'values', 'defusion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('thoughts-in-hands-distance-drill', 'Thoughts in Hands Distance Drill', 'act'::resource_kind, 'The client holds their hands over their face and then lowers them to see the difference.', 'Use it to help a client feel the difference between fusion and distance.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to cup hands over their face as if thoughts are in them, then lower them. Notice what changes and invite them to put a current thought in their hands. Debrief gently; the point is distance, not getting rid of anything.', '[{"id": "f0", "type": "textarea", "label": "A thought I am stuck on"}, {"id": "f1", "type": "textarea", "label": "How it felt with hands up"}, {"id": "f2", "type": "textarea", "label": "How it felt with hands down"}, {"id": "f3", "type": "textarea", "label": "Where I could use this in daily life"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('weekly-heading-check-against-values', 'Weekly Heading Check Against Values', 'act'::resource_kind, 'The client rates how closely their week pointed toward each chosen value.', 'Use it to help a client check direction against values, not perfection.', array['Adults', 'Teens']::text[], 'Weekly, 15 minutes', 'Pick three values and have the client rate this week''s direction for each. Treat low ratings as an invitation, not a failing. Choose one small action for the lowest one.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "How closely I lived it this week"}, {"id": "f2", "type": "textarea", "label": "What got in the way"}, {"id": "f3", "type": "textarea", "label": "One small step toward it"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('willingness-dial-practice', 'Willingness Dial Practice', 'act'::resource_kind, 'The client rates their willingness to make room for a feeling and moves the dial one notch.', 'Use it to help a client explore how much room they can make for a hard feeling.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for a rating of willingness and what the feeling is blocking. Invite just one notch of change and a way to practice it between sessions. Do not push; willingness is chosen.', '[{"id": "f0", "type": "textarea", "label": "The feeling I have been fighting"}, {"id": "f1", "type": "textarea", "label": "My willingness right now (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What making room would let me do"}, {"id": "f3", "type": "textarea", "label": "One notch I could move this week"}]'::jsonb, array['willingness', 'acceptance', 'core ACT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('stuck-points-and-sticky-stories-sort', 'Stuck Points and Sticky Stories Sort', 'act'::resource_kind, 'The client sorts the stories their mind repeats into useful and not useful for their values.', 'Use it to help a client weigh stories by workability rather than truth.', array['Adults', 'Teens']::text[], '25 minutes', 'List the recurring stories, then ask of each: when I follow this, does my life move toward what I care about? Avoid arguing content. A story can feel true and still not be useful.', '[{"id": "f0", "type": "textarea", "label": "Stories my mind tells often"}, {"id": "f1", "type": "textarea", "label": "Where following each one takes me"}, {"id": "f2", "type": "textarea", "label": "Which ones help me and which do not"}, {"id": "f3", "type": "textarea", "label": "How I will notice them next time"}]'::jsonb, array['workability', 'defusion', 'values']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('chain-analysis-walkthrough-page', 'Chain Analysis Walkthrough Page', 'dbt'::resource_kind, 'The client maps what led up to a behavior and what came after, link by link.', 'Use it to help a client see the steps between a prompting event and a behavior.', array['Adults', 'Teens']::text[], '40 minutes', 'Slow the chain down to small links: event, thoughts, feelings, body, action, result. Stay curious and non-judging. Mark places a skill could have gone in and choose one to rehearse. Do not use it when the client is highly distressed.', '[{"id": "f0", "type": "textarea", "label": "The prompting event"}, {"id": "f1", "type": "textarea", "label": "Thoughts and feelings that followed"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What happened afterward"}, {"id": "f4", "type": "textarea", "label": "A link where I could use a skill"}]'::jsonb, array['core DBT', 'skills', 'behavioral']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-skills-use', 'Pros and Cons of Skills Use', 'dbt'::resource_kind, 'The client weighs using a skill against acting on an urge for short and long term.', 'Use it to help a client decide in the moment with the long view in mind.', array['Adults', 'Teens']::text[], '20 minutes', 'Fill in four boxes with the client: acting on the urge now, resisting it, short and long term for each. Notice how the short-term column pulls and name it. Keep a copy handy for hard moments.', '[{"id": "f0", "type": "textarea", "label": "The urge"}, {"id": "f1", "type": "textarea", "label": "Acting on it: short and long term"}, {"id": "f2", "type": "textarea", "label": "Not acting on it: short and long term"}, {"id": "f3", "type": "textarea", "label": "What I decide to try"}]'::jsonb, array['distress tolerance', 'core DBT', 'urges']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('willing-hands-and-half-smile-card', 'Willing Hands and Half Smile Card', 'dbt'::resource_kind, 'The client practices softened hands and a slight smile as a way of leaning into acceptance.', 'Use it to help a client use body posture to support acceptance.', array['Adults', 'Teens']::text[], '10 minutes', 'Demonstrate palms up, hands loose, a slight lift of the lips. Practice with a mild frustration first. Check that it does not feel like pretending, and invite the client to notice any shift in tension.', '[{"id": "f0", "type": "textarea", "label": "A situation I am resisting"}, {"id": "f1", "type": "textarea", "label": "What my body does when I resist"}, {"id": "f2", "type": "textarea", "label": "What changed with willing hands"}, {"id": "f3", "type": "textarea", "label": "Where I will practice it"}]'::jsonb, array['radical acceptance', 'distress tolerance', 'core DBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('emotion-mind-wise-mind-slider', 'Emotion Mind Wise Mind Slider', 'dbt'::resource_kind, 'The client places a decision between emotion mind and reasonable mind and finds the middle.', 'Use it to help a client locate wise mind for a current choice.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw a line with emotion mind on one end and reasonable mind on the other. Have the client mark where the current decision sits and what would nudge it toward the middle. Practice a pause before acting.', '[{"id": "f0", "type": "textarea", "label": "The decision"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says"}, {"id": "f3", "type": "textarea", "label": "What wise mind says"}]'::jsonb, array['wise mind', 'core DBT', 'emotion regulation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('body-care-habits-steadiness-tracker', 'Body Care Habits Steadiness Tracker', 'dbt'::resource_kind, 'The client tracks sleep, movement and care of their body habits that make emotions steadier.', 'Use it to help a client see how basic self-care shapes emotional steadiness.', array['Adults', 'Teens']::text[], 'One week', 'Choose one or two habits rather than all of them. Review the tracker for patterns between care and mood. Keep it compassionate, and adapt for the client''s health and circumstances.', '[{"id": "f0", "type": "textarea", "label": "Sleep this week"}, {"id": "f1", "type": "textarea", "label": "Movement and rest this week"}, {"id": "f2", "type": "textarea", "label": "Care for my physical health"}, {"id": "f3", "type": "textarea", "label": "How my mood connected"}, {"id": "f4", "type": "textarea", "label": "One habit I will work on"}]'::jsonb, array['emotion regulation', 'self-monitoring', 'core DBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('sunday-sit-down-for-two-guide', 'Sunday Sit-Down for Two Guide', 'couples'::resource_kind, 'Partners hold a short structured weekly check-in about what is going well and what to adjust.', 'Use it to help partners keep small issues from piling up.', array['Couples']::text[], '30 minutes weekly', 'Teach a simple order: appreciations, what went well, one thing to change, logistics. Keep it brief and safe. Each partner fills their part and the pair agrees on one adjustment.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciated"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciated"}, {"id": "f2", "type": "textarea", "label": "Partner A: one thing to adjust"}, {"id": "f3", "type": "textarea", "label": "Partner B: one thing to adjust"}, {"id": "f4", "type": "textarea", "label": "What we agree to try"}]'::jsonb, array['couples', 'communication', 'connection']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-script', 'Stress-Reducing Conversation Script', 'couples'::resource_kind, 'One partner shares a stress from outside the relationship while the other listens and supports.', 'Use it to help partners support each other through outside stress.', array['Couples']::text[], '20 minutes', 'Set a timer and take turns. The listener asks, validates and does not fix unless asked. Ask each partner what kind of support they wanted and compare. Practice a few times before bringing in heavier topics.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the stress I am carrying"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard and asked"}, {"id": "f2", "type": "textarea", "label": "Partner B: the stress I am carrying"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I heard and asked"}, {"id": "f4", "type": "textarea", "label": "What kind of support helps each of us"}]'::jsonb, array['Gottman', 'support', 'communication']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('rituals-of-connection-menu', 'Rituals of Connection Menu', 'couples'::resource_kind, 'Partners choose small daily and weekly rituals that keep them close.', 'Use it to help partners build reliable moments of connection.', array['Couples']::text[], '25 minutes', 'Each partner lists rituals they would enjoy, then they pick two or three that work for both. Make them small and specific, like a morning coffee or a weekly walk. Check in after a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rituals I would like"}, {"id": "f1", "type": "textarea", "label": "Partner B: rituals I would like"}, {"id": "f2", "type": "textarea", "label": "The ones we both choose"}, {"id": "f3", "type": "textarea", "label": "When and how we will start"}]'::jsonb, array['connection', 'routines', 'couples']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('gentle-opening-lines-rewrite-page', 'Gentle Opening Lines Rewrite Page', 'couples'::resource_kind, 'Partners turn a harsh opening into a gentle request using their own words.', 'Use it to help partners raise a concern without starting a fight.', array['Couples']::text[], '20 minutes', 'Each partner takes a recent complaint and rewrites it as a feeling, a situation and a request. Read both aloud and notice the difference. Practice in session before real conflict.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the harsh version"}, {"id": "f1", "type": "textarea", "label": "Partner A: the softened version"}, {"id": "f2", "type": "textarea", "label": "Partner B: the harsh version"}, {"id": "f3", "type": "textarea", "label": "Partner B: the softened version"}, {"id": "f4", "type": "textarea", "label": "What changed when we said it softly"}]'::jsonb, array['Gottman', 'communication', 'conflict']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('fair-share-of-home-tasks-planner', 'Fair Share of Home Tasks Planner', 'couples'::resource_kind, 'Partners list household and care tasks, who does what, and how to share them more fairly.', 'Use it to help partners talk about workload without blame.', array['Couples']::text[], '35 minutes', 'Have each partner list tasks they do, then the tasks nobody has named. Negotiate with curiosity, not scorekeeping. Agree to a trial and a date to revisit.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I do"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I do"}, {"id": "f2", "type": "textarea", "label": "Tasks no one has claimed"}, {"id": "f3", "type": "textarea", "label": "What we will share or change"}, {"id": "f4", "type": "textarea", "label": "When we will revisit this"}]'::jsonb, array['relationships', 'planning', 'conflict']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('worry-monster-mailbox', 'Worry Monster Mailbox', 'kids'::resource_kind, 'The child draws their worry as a monster and posts it in a decorated shoebox.', 'Use it to help a child set a worry down and talk about it later.', array['Children']::text[], '30 minutes', 'Supply a box, markers and paper. The child draws the worry monster and posts it, then picks a time to open the box with you or a parent. Parent role: ask what the monster needs and stay calm and warm. Report any safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What my worry monster looks like"}, {"id": "f1", "type": "textarea", "label": "What it says"}, {"id": "f2", "type": "textarea", "label": "What I do to feel calmer"}, {"id": "f3", "type": "textarea", "label": "Who I can tell"}]'::jsonb, array['children', 'worry', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('inside-weather-spinner', 'Inside Weather Spinner', 'kids'::resource_kind, 'The child spins a wheel of weather pictures to show how they feel today.', 'Use it to help a child name feelings with simple pictures.', array['Children']::text[], '15 minutes', 'Make a paper wheel with weather pictures for feelings. Let the child spin or point, then draw what the weather is like inside. Parent role: use it at home each morning and just listen. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "Today my weather is"}, {"id": "f1", "type": "textarea", "label": "What made it that way"}, {"id": "f2", "type": "textarea", "label": "What would help my weather"}, {"id": "f3", "type": "textarea", "label": "Who I can tell"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('brave-badge-maker', 'Brave Badge Maker', 'kids'::resource_kind, 'The child designs a badge for a brave thing they did and decorates it.', 'Use it to help a child notice and celebrate their own brave moments.', array['Children']::text[], '25 minutes', 'Use paper, stickers and a safety pin or tape. Ask for a brave moment and have the child design a badge. Parent role: ask about it and display it, avoiding comparison with others. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "A brave thing I did"}, {"id": "f1", "type": "textarea", "label": "What I felt before and after"}, {"id": "f2", "type": "textarea", "label": "What my badge looks like"}, {"id": "f3", "type": "textarea", "label": "Who I will show it to"}]'::jsonb, array['children', 'strengths', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('calm-down-jar', 'Calm Down Jar', 'kids'::resource_kind, 'The child fills a jar with water and glitter and watches it settle while breathing slowly.', 'Use it to help a child have a hands-on way to slow down.', array['Children']::text[], '25 minutes', 'Make the jar together and shake it, then breathe slowly while the glitter settles. Practice when calm so it is ready when upset. Parent role: offer the jar without pressure and sit nearby. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What I felt when I shook it"}, {"id": "f1", "type": "textarea", "label": "What I noticed while it settled"}, {"id": "f2", "type": "textarea", "label": "When I will use my jar"}, {"id": "f3", "type": "textarea", "label": "How my body feels now"}]'::jsonb, array['children', 'self-soothing', 'play']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('kindness-cards-treasure-hunt', 'Kindness Cards Treasure Hunt', 'kids'::resource_kind, 'The child hides and finds cards with small kind acts to do for others and themselves.', 'Use it to help a child practice kind actions in a playful way.', array['Children']::text[], '30 minutes', 'Write simple acts on cards, hide them and let the child find and do them. Include some for themselves. Parent role: join in and notice kindness without turning it into a chore. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "A kind act I did"}, {"id": "f1", "type": "textarea", "label": "How it felt"}, {"id": "f2", "type": "textarea", "label": "A kind thing I did for myself"}, {"id": "f3", "type": "textarea", "label": "A kind act I want to try next"}]'::jsonb, array['children', 'play', 'connection']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('skills-bingo', 'Skills Bingo', 'game'::resource_kind, 'Players mark squares when they use a coping skill during the week.', 'Use it to help clients practice and remember coping skills playfully.', array['Adults', 'Teens', 'Groups']::text[], 'One week, then a 20 minute debrief', 'Make a card of skills like breathing, a walk, a call to a friend. Players mark a square when they try one. Rules: one mark per skill per day, no penalties. Debrief on what worked and what to try again.', '[{"id": "f0", "type": "textarea", "label": "Skills I marked"}, {"id": "f1", "type": "textarea", "label": "The one that helped most"}, {"id": "f2", "type": "textarea", "label": "The one I want to try again"}, {"id": "f3", "type": "textarea", "label": "What stopped me from others"}]'::jsonb, array['game', 'coping skills', 'skills']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('emotion-charades', 'Emotion Charades', 'game'::resource_kind, 'Players act out feelings without words while others guess, then talk about when they felt it.', 'Use it to help clients label emotions and share when they happen.', array['Teens', 'Groups', 'Children']::text[], '25 minutes', 'Rules: take turns drawing a card, act it silently, others guess. The actor says one time they felt it, if they want to. Debrief on how bodies show feelings. Passing is always fine.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted out"}, {"id": "f1", "type": "textarea", "label": "How my body shows it"}, {"id": "f2", "type": "textarea", "label": "A time I felt it"}, {"id": "f3", "type": "textarea", "label": "What I learned from others'' acting"}]'::jsonb, array['game', 'emotion identification', 'group']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('values-sort-showdown', 'Values Sort Showdown', 'game'::resource_kind, 'Players race to sort value cards into must-have, nice-to-have and not-for-me piles.', 'Use it to help clients clarify what matters through a quick sorting game.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Rules: each player sorts cards in a few minutes, then explains their top three. Turns alternate between sorting and listening. Debrief on surprises and one action that fits a top value.', '[{"id": "f0", "type": "textarea", "label": "My top three values"}, {"id": "f1", "type": "textarea", "label": "What surprised me"}, {"id": "f2", "type": "textarea", "label": "Where my week fits them"}, {"id": "f3", "type": "textarea", "label": "One action I will take"}]'::jsonb, array['game', 'values', 'group']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('specific-thanks-round-robin', 'Specific Thanks Round Robin', 'game'::resource_kind, 'Group members take turns offering one specific, true appreciation to the person beside them.', 'Use it to help group members give and receive appreciation.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: go around the circle, each person gives a specific, kind and true comment about behavior, not looks. The receiver says thank you only. Debrief on how it felt to receive. Anyone may pass.', '[{"id": "f0", "type": "textarea", "label": "What I heard about myself"}, {"id": "f1", "type": "textarea", "label": "How it felt to receive it"}, {"id": "f2", "type": "textarea", "label": "What I said to someone else"}, {"id": "f3", "type": "textarea", "label": "A strength I want to keep using"}]'::jsonb, array['game', 'group', 'appreciation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('problem-solving-dice', 'Problem Solving Dice', 'game'::resource_kind, 'Players roll for a pretend problem and brainstorm solutions in turns.', 'Use it to help clients practice generating several options for a problem.', array['Teens', 'Groups', 'Children']::text[], '25 minutes', 'Rules: roll to choose a scenario card and a time limit. Each player offers one idea per round, with no judging. Pick the best together. Debrief on how to use the same steps on a real issue.', '[{"id": "f0", "type": "textarea", "label": "The problem I rolled"}, {"id": "f1", "type": "textarea", "label": "Ideas we came up with"}, {"id": "f2", "type": "textarea", "label": "The one I would choose"}, {"id": "f3", "type": "textarea", "label": "A real problem I could try this on"}]'::jsonb, array['game', 'problem solving', 'coping skills']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('safe-places-inventory', 'Safe Places Inventory', 'worksheet'::resource_kind, 'The client lists places, people and objects that feel steady and notes how each helps.', 'Use it to help a client build a list of steady anchors for hard moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep this to the present. Ask for places and people that feel steady today and how the client notices it in the body. No need to describe past events. Review the list and pick two to use this week.', '[{"id": "f0", "type": "textarea", "label": "Places that feel steady"}, {"id": "f1", "type": "textarea", "label": "People who help me feel safe"}, {"id": "f2", "type": "textarea", "label": "Objects that comfort me"}, {"id": "f3", "type": "textarea", "label": "How I notice steadiness in my body"}, {"id": "f4", "type": "textarea", "label": "Two I will use this week"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'safety']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('stuck-point-log-for-present-moments', 'Stuck Point Log for Present Moments', 'cbt'::resource_kind, 'The client notes a recent moment of feeling on edge and the thought that went with it.', 'Use it to help a client spot present-day thoughts that keep them on alert.', array['Adults']::text[], '25 minutes', 'Stay with recent everyday moments, not the original events. Have the client write the situation, the thought and a more balanced version. Go slowly, and stop to ground if the client becomes overwhelmed.', '[{"id": "f0", "type": "textarea", "label": "A recent moment I felt on edge"}, {"id": "f1", "type": "textarea", "label": "The thought that went with it"}, {"id": "f2", "type": "textarea", "label": "How strongly I believed it"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}, {"id": "f4", "type": "textarea", "label": "What helps me feel steady"}]'::jsonb, array['PTSD and trauma', 'thought record', 'stabilizing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('choosing-direction-after-hard-times', 'Choosing Direction After Hard Times', 'act'::resource_kind, 'The client names what they want their life to be about and one step toward it today.', 'Use it to help a client reconnect with values at their own pace.', array['Adults']::text[], '30 minutes', 'Begin with what matters now, not what happened. Let the client pick a value and a very small step. Pace is theirs, and noticing the body between steps is part of the work.', '[{"id": "f0", "type": "textarea", "label": "What matters to me now"}, {"id": "f1", "type": "textarea", "label": "What I would like more of"}, {"id": "f2", "type": "textarea", "label": "A very small step I can take"}, {"id": "f3", "type": "textarea", "label": "What helps me stay steady while I do it"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('grounding-with-five-senses-card', 'Grounding With Five Senses Card', 'dbt'::resource_kind, 'The client builds a pocket card of sights, sounds, touches, smells and tastes that anchor them.', 'Use it to help a client carry a quick grounding routine.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client choose items for each sense that are actually available in daily life. Practice once in session and once between. Adjust if any sense feels uncomfortable; skip it.', '[{"id": "f0", "type": "textarea", "label": "Something I can see"}, {"id": "f1", "type": "textarea", "label": "Something I can hear"}, {"id": "f2", "type": "textarea", "label": "Something I can touch"}, {"id": "f3", "type": "textarea", "label": "Something I can smell or taste"}, {"id": "f4", "type": "textarea", "label": "When I will use this card"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('anchor-cards-matching-game', 'Anchor Cards Matching Game', 'game'::resource_kind, 'Players match anchor cards to moments when they might need them and practice one together.', 'Use it to help clients rehearse grounding in a calm, low-pressure way.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Rules: lay out anchor cards and situation cards, take turns matching, and say why. Try one anchor together. Keep content to everyday moments. Debrief on which anchor fit best.', '[{"id": "f0", "type": "textarea", "label": "The anchor I matched"}, {"id": "f1", "type": "textarea", "label": "The moment I might use it"}, {"id": "f2", "type": "textarea", "label": "How it felt to practice"}, {"id": "f3", "type": "textarea", "label": "What I will carry with me"}]'::jsonb, array['PTSD and trauma', 'game', 'grounding', 'stabilizing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('worry-time-container-sheet', 'Worry Time Container Sheet', 'worksheet'::resource_kind, 'The client sets a short daily time for worries and parks others on paper until then.', 'Use it to help a client contain worry to a set part of the day.', array['Adults', 'Teens']::text[], 'One week', 'Choose a consistent twenty minute slot away from bedtime. During the day the client jots a worry and returns to the task. At worry time they review and sort what can be acted on. Expect it to take a few days to settle.', '[{"id": "f0", "type": "textarea", "label": "My worry time"}, {"id": "f1", "type": "textarea", "label": "Worries I parked this week"}, {"id": "f2", "type": "textarea", "label": "Ones I can act on"}, {"id": "f3", "type": "textarea", "label": "Ones I can let go of"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('what-is-the-worst-best-and-most-likely', 'What Is the Worst, Best and Most Likely', 'cbt'::resource_kind, 'The client writes three versions of a feared outcome and a plan for each.', 'Use it to help a client widen their view of what might happen.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write all three outcomes and a coping plan for the worst. Look at which one they spend the most time on. The aim is a fuller picture, not reassurance.', '[{"id": "f0", "type": "textarea", "label": "What I fear"}, {"id": "f1", "type": "textarea", "label": "The worst that could happen"}, {"id": "f2", "type": "textarea", "label": "The best that could happen"}, {"id": "f3", "type": "textarea", "label": "The most likely outcome"}, {"id": "f4", "type": "textarea", "label": "How I would cope"}]'::jsonb, array['anxiety', 'thinking traps']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('anxiety-passenger-check-in', 'Anxiety Passenger Check-In', 'act'::resource_kind, 'The client notices anxiety as a passenger and chooses one action while it rides along.', 'Use it to help a client act on values with anxiety present.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask where the client feels anxiety, what it tells them to do, and what they would do if it came along. Choose one small action and plan how to notice the urge to avoid.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anxiety"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I want to do instead"}, {"id": "f3", "type": "textarea", "label": "The step I will take this week"}]'::jsonb, array['anxiety', 'defusion', 'values', 'avoidance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('half-smile-and-paced-breathing-practice', 'Half Smile and Paced Breathing Practice', 'dbt'::resource_kind, 'The client pairs a gentle half smile with slow breaths to settle during worry.', 'Use it to help a client use the body to settle during anxiety.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice in session with a mild worry first. Count breaths out longer than in. Check comfort with the half smile and adapt.', '[{"id": "f0", "type": "textarea", "label": "A worry I practiced with"}, {"id": "f1", "type": "textarea", "label": "How my body felt before"}, {"id": "f2", "type": "textarea", "label": "How my body felt after"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['anxiety', 'breathing', 'distress tolerance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('paper-dragon-worry-keeper', 'Paper Dragon Worry Keeper', 'kids'::resource_kind, 'The child builds a paper dragon for their worry and plans a way to tame it.', 'Use it to help a child make worry feel smaller and more manageable.', array['Children']::text[], '30 minutes', 'Provide paper and craft supplies. The child makes the dragon, names its fears and picks ways to calm it. Parent role: stay curious, praise trying and avoid rescuing. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What my dragon worries about"}, {"id": "f1", "type": "textarea", "label": "How big my dragon is"}, {"id": "f2", "type": "textarea", "label": "What helps calm it"}, {"id": "f3", "type": "textarea", "label": "Who helps me tame it"}]'::jsonb, array['anxiety', 'children', 'worry', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('tiny-wins-jar-page', 'Tiny Wins Jar Page', 'worksheet'::resource_kind, 'The client records one small thing they did each day and files it in a jar.', 'Use it to help a client notice effort on low days.', array['Adults', 'Teens']::text[], 'One week', 'Keep the bar very low: getting out of bed or eating lunch counts. Review the page without praise inflation. Ask which tiny thing felt best and plan one for tomorrow.', '[{"id": "f0", "type": "textarea", "label": "A tiny thing I did today"}, {"id": "f1", "type": "textarea", "label": "How it felt"}, {"id": "f2", "type": "textarea", "label": "What made it possible"}, {"id": "f3", "type": "textarea", "label": "One tiny thing for tomorrow"}]'::jsonb, array['depression', 'behavioral activation', 'strengths']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('pleasure-and-mastery-scheduler', 'Pleasure and Mastery Scheduler', 'cbt'::resource_kind, 'The client plans activities that bring enjoyment or a sense of accomplishment and rates them after.', 'Use it to help a client rebuild routines that feel worthwhile.', array['Adults', 'Teens']::text[], 'One week', 'Plan a few small activities and rate enjoyment and accomplishment afterward. Notice predictions that it will not help. Adjust based on what the client reports, not on what they think should work.', '[{"id": "f0", "type": "textarea", "label": "Activities I planned"}, {"id": "f1", "type": "textarea", "label": "How much I expected to enjoy them"}, {"id": "f2", "type": "textarea", "label": "How much I enjoyed them"}, {"id": "f3", "type": "textarea", "label": "What I will repeat"}]'::jsonb, array['depression', 'behavioral activation', 'monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('five-minute-values-action-planner', 'Five-Minute Values Action Planner', 'act'::resource_kind, 'The client picks a value and a five-minute action that fits it on low-energy days.', 'Use it to help a client act on values when energy is low.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one value and a five-minute version of acting on it. Name the mood that will argue against it. The client is choosing a direction, not forcing a mood.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "A five-minute way to act on it"}, {"id": "f2", "type": "textarea", "label": "What my mood will say"}, {"id": "f3", "type": "textarea", "label": "What I will do anyway"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('low-mood-urge-flip-card', 'Low Mood Urge Flip Card', 'dbt'::resource_kind, 'The client names the urge that comes with low mood and plans an opposite action.', 'Use it to help a client act against the urge to withdraw when it does not fit the facts.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client identify the urge, check whether it fits the facts, then plan a small opposite step like texting a friend. Practice fully, including posture. Pair with willingness.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice"}, {"id": "f1", "type": "textarea", "label": "Does it fit the facts"}, {"id": "f2", "type": "textarea", "label": "The opposite action"}, {"id": "f3", "type": "textarea", "label": "When I will try it"}]'::jsonb, array['depression', 'opposite action', 'emotion regulation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('support-during-low-mood-conversation-guide', 'Support During Low Mood Conversation Guide', 'couples'::resource_kind, 'Partners talk about what helps and does not help when one of them is feeling low.', 'Use it to help partners agree on how to support each other.', array['Couples']::text[], '30 minutes', 'Invite the partner who feels low to describe what helps and what does not, and the other to share how they feel as a helper. Agree on a few phrases and a signal. Keep it collaborative.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when I feel low"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I feel when I help"}, {"id": "f2", "type": "textarea", "label": "What we will say and do"}, {"id": "f3", "type": "textarea", "label": "How we will check back in"}]'::jsonb, array['depression', 'support', 'communication', 'couples']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('launch-pad-routine-sheet', 'Launch Pad Routine Sheet', 'worksheet'::resource_kind, 'The client designs a spot by the door holding everything needed to leave on time.', 'Use it to help a client reduce last-minute searching before leaving.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the client''s usual exit and list what goes missing. Build the launch pad with a tray, hook and checklist. Review next session and adjust to what actually gets used.', '[{"id": "f0", "type": "textarea", "label": "Things I lose or forget"}, {"id": "f1", "type": "textarea", "label": "What goes on my launch pad"}, {"id": "f2", "type": "textarea", "label": "Where it will live"}, {"id": "f3", "type": "textarea", "label": "How I will remember to use it"}]'::jsonb, array['ADHD', 'executive function', 'routines']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('time-estimate-versus-actual-log', 'Time Estimate Versus Actual Log', 'cbt'::resource_kind, 'The client guesses how long tasks take, times them and compares.', 'Use it to help a client calibrate time estimates with real data.', array['Adults', 'Teens']::text[], 'One week', 'Choose three recurring tasks. The client predicts, times and records the gap. Look for patterns and build in a buffer. Keep it curious, not critical.', '[{"id": "f0", "type": "textarea", "label": "The task"}, {"id": "f1", "type": "textarea", "label": "My guess"}, {"id": "f2", "type": "textarea", "label": "How long it took"}, {"id": "f3", "type": "textarea", "label": "What I will plan for next time"}]'::jsonb, array['ADHD', 'executive function', 'self-monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('interest-versus-importance-map', 'Interest Versus Importance Map', 'act'::resource_kind, 'The client sorts tasks by what grabs them and what matters to them and plans how to bridge the gap.', 'Use it to help a client act on important but boring tasks.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort tasks into interesting, important, both and neither. For important but dull ones, plan a way to make them easier to start. Tie each back to a value.', '[{"id": "f0", "type": "textarea", "label": "Tasks that interest me"}, {"id": "f1", "type": "textarea", "label": "Tasks that matter to me"}, {"id": "f2", "type": "textarea", "label": "Important but boring ones"}, {"id": "f3", "type": "textarea", "label": "How I will make them easier to start"}]'::jsonb, array['ADHD', 'values', 'task initiation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('mindful-attention-anchor-practice', 'Mindful Attention Anchor Practice', 'dbt'::resource_kind, 'The client practices returning attention to one anchor for short rounds and logs each return.', 'Use it to help a client practice noticing and returning attention.', array['Adults', 'Teens']::text[], 'Five minutes daily for several weeks', 'Use one anchor such as breath or sound for two or three minutes. Count returns as successes. Increase length slowly and keep the tone playful.', '[{"id": "f0", "type": "textarea", "label": "My anchor"}, {"id": "f1", "type": "textarea", "label": "How many times I wandered and returned"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention"}, {"id": "f3", "type": "textarea", "label": "How it felt afterward"}]'::jsonb, array['ADHD', 'attention', 'mindfulness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('one-step-obstacle-trail', 'One Step Obstacle Trail', 'kids'::resource_kind, 'The child builds a small obstacle course and practices doing one step at a time.', 'Use it to help a child practice sequencing and focus through movement.', array['Children']::text[], '30 minutes', 'Build the course with cushions and tape and add a card with each step. The child completes one step at a time. Parent role: cheer, give one instruction at a time and avoid rushing. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What my steps were"}, {"id": "f1", "type": "textarea", "label": "Which step was hardest"}, {"id": "f2", "type": "textarea", "label": "What helped me focus"}, {"id": "f3", "type": "textarea", "label": "Who helps me"}]'::jsonb, array['ADHD', 'children', 'attention', 'play']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('urge-surfing-log', 'Urge Surfing Log', 'worksheet'::resource_kind, 'The client records an urge, how it rose and fell, and what they did in the meantime.', 'Use it to help a client see that an urge to use a substance passes.', array['Adults']::text[], 'One week', 'Have the client log the time, intensity from 0 to 10, what they did and when it eased. Look for patterns in time and place. Talk about safe supports and note any substance use without judgment.', '[{"id": "f0", "type": "textarea", "label": "When the urge started"}, {"id": "f1", "type": "textarea", "label": "How strong it felt"}, {"id": "f2", "type": "textarea", "label": "What I did while it passed"}, {"id": "f3", "type": "textarea", "label": "When it eased"}]'::jsonb, array['addiction', 'urges', 'substance use', 'self-monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('high-risk-situations-plan', 'High-Risk Situations Plan', 'cbt'::resource_kind, 'The client lists places and moods that raise urges and a plan for each.', 'Use it to help a client plan ahead for moments that raise urges.', array['Adults']::text[], '35 minutes', 'Work through concrete situations and write a plan for each. Include who they can call. Review which plans felt realistic and rehearse one. Keep language about substance use and urges, not labels.', '[{"id": "f0", "type": "textarea", "label": "Situations that raise urges"}, {"id": "f1", "type": "textarea", "label": "The plan for each"}, {"id": "f2", "type": "textarea", "label": "Who I can contact"}, {"id": "f3", "type": "textarea", "label": "What I will do if the plan slips"}]'::jsonb, array['addiction', 'substance use', 'planning', 'urges']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('values-beyond-substance-use-page', 'Values Beyond Substance Use Page', 'act'::resource_kind, 'The client names what they want their days to hold and what substance use has cost or crowded out.', 'Use it to help a client link recovery steps to what matters.', array['Adults']::text[], '30 minutes', 'Ask what the client values, what has been crowded out and one step toward it. Avoid shaming. Note that urges may be present and that a step can be taken with them.', '[{"id": "f0", "type": "textarea", "label": "What matters to me"}, {"id": "f1", "type": "textarea", "label": "What I want more room for"}, {"id": "f2", "type": "textarea", "label": "One step this week"}, {"id": "f3", "type": "textarea", "label": "What I will do when an urge shows up"}]'::jsonb, array['addiction', 'values', 'substance use', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('urge-peak-skills-menu', 'Urge Peak Skills Menu', 'dbt'::resource_kind, 'The client builds a menu of skills to use when an urge peaks.', 'Use it to help a client reach for a skill when an urge is strong.', array['Adults', 'Teens']::text[], '30 minutes', 'Group skills by type: distract, self-soothe, change body chemistry, improve the moment. The client picks favorites and practices one. Keep the menu somewhere easy to reach.', '[{"id": "f0", "type": "textarea", "label": "Distractions I can use"}, {"id": "f1", "type": "textarea", "label": "Ways I can self-soothe"}, {"id": "f2", "type": "textarea", "label": "Ways to change my body state"}, {"id": "f3", "type": "textarea", "label": "My top three for this week"}]'::jsonb, array['addiction', 'distress tolerance', 'urges', 'substance use']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('supporting-each-other-around-substance-use-talk', 'Supporting Each Other Around Substance Use Talk', 'couples'::resource_kind, 'Partners agree on how to talk about substance use and urges and what support looks like.', 'Use it to help partners plan supportive conversation.', array['Couples']::text[], '30 minutes', 'Each partner shares what helps, what does not and what they fear. Agree on words to use and a pause signal. Keep it about behavior and needs, not blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need"}, {"id": "f2", "type": "textarea", "label": "What we will say"}, {"id": "f3", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['addiction', 'couples', 'substance use', 'support']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('anger-warning-signs-body-map', 'Anger Warning Signs Body Map', 'worksheet'::resource_kind, 'The client marks where in the body anger first shows up and in what order.', 'Use it to help a client notice early signs before anger peaks.', array['Adults', 'Teens']::text[], '25 minutes', 'Hand over an outline and have the client mark early signs like jaw, heat or fists. Rank them in order. Plan one action at the first sign.', '[{"id": "f0", "type": "textarea", "label": "Early body signs"}, {"id": "f1", "type": "textarea", "label": "Later body signs"}, {"id": "f2", "type": "textarea", "label": "Thoughts that come with them"}, {"id": "f3", "type": "textarea", "label": "What I will do at the first sign"}]'::jsonb, array['anger management', 'body awareness', 'de-escalation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('anger-triggers-and-hot-thoughts-record', 'Anger Triggers and Hot Thoughts Record', 'cbt'::resource_kind, 'The client notes a trigger, the hot thought and a more balanced alternative.', 'Use it to help a client see the thought between a trigger and anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recent episode and slow it down. Look for words like should and always. Write a more balanced thought and notice if intensity shifts.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "The hot thought"}, {"id": "f2", "type": "textarea", "label": "How intense the anger was"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}]'::jsonb, array['anger management', 'thought record', 'thinking traps']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('anger-as-messenger-reflection', 'Anger as Messenger Reflection', 'act'::resource_kind, 'The client asks what matters to them underneath anger and picks a values-based response.', 'Use it to help a client choose a response that fits their values.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the anger is protecting. Name the value, then list ways to act on it that do not harm. Rehearse the first words they would say.', '[{"id": "f0", "type": "textarea", "label": "What was happening"}, {"id": "f1", "type": "textarea", "label": "What anger is protecting"}, {"id": "f2", "type": "textarea", "label": "What I want to stand for"}, {"id": "f3", "type": "textarea", "label": "What I could do or say instead"}]'::jsonb, array['anger management', 'values']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('tip-skills-cool-down-card', 'TIP Skills Cool-Down Card', 'dbt'::resource_kind, 'The client practices changing body temperature, intense exercise, paced breathing and relaxation to come down.', 'Use it to help a client lower arousal quickly.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach each part and let the client choose which to practice. Adapt for health or medication concerns and ask them to check with their doctor first where relevant. Rehearse before they need it.', '[{"id": "f0", "type": "textarea", "label": "Which part I tried"}, {"id": "f1", "type": "textarea", "label": "How intense I felt before"}, {"id": "f2", "type": "textarea", "label": "How intense I felt after"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['anger management', 'distress tolerance', 'regulation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('cool-skill-pass-along-game', 'Cool Skill Pass-Along Game', 'game'::resource_kind, 'Teams take turns drawing a cooling skill card, demonstrating it and passing the card on.', 'Use it to help groups rehearse anger de-escalation skills.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: take turns drawing a card, show or explain the skill, and the group says when they might use it. No pressure to share personal stories. Debrief on which skills fit which situations.', '[{"id": "f0", "type": "textarea", "label": "The skill I drew"}, {"id": "f1", "type": "textarea", "label": "When I could use it"}, {"id": "f2", "type": "textarea", "label": "The one I will try"}, {"id": "f3", "type": "textarea", "label": "What I noticed about others'' skills"}]'::jsonb, array['anger management', 'game', 'de-escalation']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('ritual-time-and-cost-ledger', 'Ritual Time and Cost Ledger', 'worksheet'::resource_kind, 'The client lists how much time and energy rituals take and what that time could hold instead.', 'Use it to help a client weigh the cost of rituals against what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client log rituals and the time or plans they cost. Link each to a value without arguing about the thought. Choose one ritual to explore with the client''s consent.', '[{"id": "f0", "type": "textarea", "label": "Rituals I do"}, {"id": "f1", "type": "textarea", "label": "Time they take"}, {"id": "f2", "type": "textarea", "label": "What I am missing"}, {"id": "f3", "type": "textarea", "label": "What I would do with that time"}]'::jsonb, array['OCD', 'values', 'self-monitoring']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('exposure-ladder-with-ritual-delay', 'Exposure Ladder With Ritual Delay', 'cbt'::resource_kind, 'The client ranks feared situations and practices delaying the ritual by small steps.', 'Use it to help a client work up a graded plan at their own pace.', array['Adults', 'Teens']::text[], '35 minutes', 'Build the ladder together and begin with a step the client rates as manageable. Practice delaying the urge to ritualize and record what happened. Go at the client''s pace and review each step.', '[{"id": "f0", "type": "textarea", "label": "Situations on my ladder"}, {"id": "f1", "type": "textarea", "label": "Ranking from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Which one I will start with"}, {"id": "f3", "type": "textarea", "label": "What I noticed after"}]'::jsonb, array['OCD', 'exposure', 'hierarchy']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('making-room-for-doubt-exercise', 'Making Room for Doubt Exercise', 'act'::resource_kind, 'The client practices carrying a doubt without answering it and chooses a values-based action.', 'Use it to help a client act with uncertainty present.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the doubt, then label it as a thought. Choose one action the client cares about and do it while the doubt is present. Avoid reassurance, which keeps doubt going.', '[{"id": "f0", "type": "textarea", "label": "The doubt"}, {"id": "f1", "type": "textarea", "label": "What it asks me to do"}, {"id": "f2", "type": "textarea", "label": "What I will do instead"}, {"id": "f3", "type": "textarea", "label": "How I handled the uncertainty"}]'::jsonb, array['OCD', 'uncertainty', 'defusion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('wise-mind-pause-before-rituals', 'Wise Mind Pause Before Rituals', 'dbt'::resource_kind, 'The client pauses, checks in with wise mind and chooses what to do with an urge.', 'Use it to help a client create space between an urge and a ritual.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice a breath and a wise mind question before acting. Review times the client paused and what changed. A pause of a few minutes is enough to begin.', '[{"id": "f0", "type": "textarea", "label": "The urge"}, {"id": "f1", "type": "textarea", "label": "What my emotion mind said"}, {"id": "f2", "type": "textarea", "label": "What wise mind said"}, {"id": "f3", "type": "textarea", "label": "What I did"}]'::jsonb, array['OCD', 'wise mind', 'urges']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('bossy-voice-comic-page', 'Bossy Voice Comic Page', 'kids'::resource_kind, 'The child draws a comic about a bossy brain and how they talk back.', 'Use it to help a child separate themselves from intrusive worries.', array['Children']::text[], '30 minutes', 'Provide comic paper. The child draws what the bossy brain says and a hero reply. Parent role: avoid answering the worry or giving reassurance, and praise brave tries. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What my bossy brain says"}, {"id": "f1", "type": "textarea", "label": "What I say back"}, {"id": "f2", "type": "textarea", "label": "What I do instead"}, {"id": "f3", "type": "textarea", "label": "Who helps me"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('panic-sensations-map-and-facts', 'Panic Sensations Map and Facts', 'worksheet'::resource_kind, 'The client lists body sensations during panic and the facts about each.', 'Use it to help a client understand sensations through accurate information.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list sensations and what they feared. Share simple facts about the body''s alarm system and let them put it in their own words. Note that a medical check is the client''s call.', '[{"id": "f0", "type": "textarea", "label": "Sensations I notice"}, {"id": "f1", "type": "textarea", "label": "What I fear they mean"}, {"id": "f2", "type": "textarea", "label": "Facts I have learned"}, {"id": "f3", "type": "textarea", "label": "What I tell myself now"}]'::jsonb, array['panic attacks', 'psychoeducation', 'body awareness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('body-sensation-practice-record', 'Body Sensation Practice Record', 'cbt'::resource_kind, 'The client practices harmless sensations like spinning or paced breathing and records reactions.', 'Use it to help a client practice sensations they fear in a planned way.', array['Adults', 'Teens']::text[], '30 minutes', 'Check the client''s health first and let them choose which sensation to try. Practice in session, then at home. Record intensity and what they learned. Stop if distress is too high.', '[{"id": "f0", "type": "textarea", "label": "Exercise I tried"}, {"id": "f1", "type": "textarea", "label": "Sensations I noticed"}, {"id": "f2", "type": "textarea", "label": "How scary it felt (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "What I learned"}]'::jsonb, array['panic attacks', 'exposure', 'behavioral experiment']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-it-panic-practice', 'Willing to Feel It Panic Practice', 'act'::resource_kind, 'The client practices staying with sensations while doing something they value.', 'Use it to help a client do valued things with sensations present.', array['Adults', 'Teens']::text[], '25 minutes', 'Name the sensations and thoughts, then pick one valued activity to do anyway. Review what it was like to let sensations come and go. Stay curious, not forceful.', '[{"id": "f0", "type": "textarea", "label": "What I notice in my body"}, {"id": "f1", "type": "textarea", "label": "What my mind says"}, {"id": "f2", "type": "textarea", "label": "A valued thing I will do anyway"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['panic attacks', 'willingness', 'values']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-grounding-combo', 'Paced Breathing and Grounding Combo', 'dbt'::resource_kind, 'The client pairs slow paced breathing with a five-sense grounding step.', 'Use it to help a client settle during a surge of sensations.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach a long out-breath and pair it with naming things seen and heard. Practice when calm. Let the client modify the pace and note whether the skill is helpful.', '[{"id": "f0", "type": "textarea", "label": "What I noticed"}, {"id": "f1", "type": "textarea", "label": "How my breath changed"}, {"id": "f2", "type": "textarea", "label": "What I named"}, {"id": "f3", "type": "textarea", "label": "When I will use this"}]'::jsonb, array['panic attacks', 'grounding', 'breathing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('surge-surfing-board-game', 'Surge Surfing Board Game', 'game'::resource_kind, 'Players move along a board of sensations and draw cards that offer ways to ride them out.', 'Use it to help clients rehearse riding out sensations in a playful way.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Rules: roll to move, draw a skill card, say how you would use it. Turns rotate, and passing is fine. Debrief on which skills fit and what to practice this week.', '[{"id": "f0", "type": "textarea", "label": "A square I landed on"}, {"id": "f1", "type": "textarea", "label": "The skill I used"}, {"id": "f2", "type": "textarea", "label": "What I will practice"}, {"id": "f3", "type": "textarea", "label": "What I learned from others"}]'::jsonb, array['panic attacks', 'game', 'coping skills']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('child-led-ten-minutes-planner', 'Child-Led Ten Minutes Planner', 'worksheet'::resource_kind, 'The parent plans short, child-led play time and notes how it went.', 'Use it to help a parent set up regular one-on-one time with their child.', array['Adults']::text[], 'One week', 'Aim for ten minutes a day where the child leads and the parent describes and enjoys. Review what the parent noticed in themselves. Keep it small and doable.', '[{"id": "f0", "type": "textarea", "label": "Times I can set aside"}, {"id": "f1", "type": "textarea", "label": "What my child chose to do"}, {"id": "f2", "type": "textarea", "label": "What I said and did"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}, {"id": "f4", "type": "textarea", "label": "What I will adjust"}]'::jsonb, array['parenting', 'connection', 'routines']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('after-the-meltdown-thought-check-for-parents', 'After the Meltdown Thought Check for Parents', 'cbt'::resource_kind, 'The parent catches the thought behind a frustrating moment and writes a balanced one.', 'Use it to help a parent respond with more room after a hard moment.', array['Adults']::text[], '25 minutes', 'Choose a recent hard moment. Look for thoughts like he is doing it on purpose. Write a balanced version and a calmer response to try next time.', '[{"id": "f0", "type": "textarea", "label": "The moment"}, {"id": "f1", "type": "textarea", "label": "What I thought about my child"}, {"id": "f2", "type": "textarea", "label": "What I felt and did"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['parenting', 'thought record']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('parent-i-want-to-be-page', 'Parent I Want to Be Page', 'act'::resource_kind, 'The parent names the kind of parent they want to be and one daily action that fits.', 'Use it to help a parent act on values even when worn out.', array['Adults']::text[], '25 minutes', 'Ask what the parent wants their child to remember. Pick values and one action for tonight. Name the thoughts that get in the way and how they will carry them.', '[{"id": "f0", "type": "textarea", "label": "The parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A value behind that"}, {"id": "f2", "type": "textarea", "label": "One action today"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('validate-then-guide-practice-page', 'Validate, Then Guide Practice Page', 'dbt'::resource_kind, 'The parent practices validating a child''s feeling before setting a limit.', 'Use it to help a parent pair warmth with a clear limit.', array['Adults']::text[], '25 minutes', 'Role-play a scene: name the feeling, show understanding, then state the limit calmly. Have the parent write a script they can use and practice once aloud.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The feeling I will name"}, {"id": "f2", "type": "textarea", "label": "What I will say to validate"}, {"id": "f3", "type": "textarea", "label": "The limit I will hold"}]'::jsonb, array['parenting', 'communication', 'interpersonal effectiveness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('co-parenting-plan-check-in', 'Co-Parenting Plan Check-In', 'couples'::resource_kind, 'Parents agree on routines, responses and how to back each other up.', 'Use it to help parents get on the same page about shared child care.', array['Couples']::text[], '35 minutes', 'Each parent writes their top concerns and what they appreciate in the other. Choose two shared rules and how to back each other in front of the child. Revisit in two weeks.', '[{"id": "f0", "type": "textarea", "label": "Parent A: my top concern"}, {"id": "f1", "type": "textarea", "label": "Parent B: my top concern"}, {"id": "f2", "type": "textarea", "label": "Two rules we agree on"}, {"id": "f3", "type": "textarea", "label": "How we back each other up"}]'::jsonb, array['parenting', 'couples', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('support-circle-map-for-new-parents', 'Support Circle Map for New Parents', 'worksheet'::resource_kind, 'The parent maps who can help with what in the first months with a baby.', 'Use it to help a new parent line up concrete support.', array['Adults']::text[], '25 minutes', 'Draw circles for close, wider and professional support and write specific help beside each name. Ask who the parent finds hard to ask. Plan one ask this week.', '[{"id": "f0", "type": "textarea", "label": "People close to me"}, {"id": "f1", "type": "textarea", "label": "What each could help with"}, {"id": "f2", "type": "textarea", "label": "Who is hard to ask"}, {"id": "f3", "type": "textarea", "label": "One ask I will make this week"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('should-thoughts-for-new-parents-record', 'Should Thoughts for New Parents Record', 'cbt'::resource_kind, 'The parent catches unforgiving should thoughts about parenting and writes kinder ones.', 'Use it to help a parent ease harsh expectations.', array['Adults']::text[], '25 minutes', 'List the should statements and where they come from. Rewrite each as a preference or a kind guideline. Notice how the new wording feels.', '[{"id": "f0", "type": "textarea", "label": "A should I say to myself"}, {"id": "f1", "type": "textarea", "label": "Where it comes from"}, {"id": "f2", "type": "textarea", "label": "Is it fair and realistic"}, {"id": "f3", "type": "textarea", "label": "A kinder way to say it"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('good-enough-parenting-values-page', 'Good Enough Parenting Values Page', 'act'::resource_kind, 'The parent names what matters most to them in this season and lets go of the rest.', 'Use it to help a parent focus on what matters while stretched thin.', array['Adults']::text[], '25 minutes', 'Ask what matters most right now and what can wait. Name the voice of comparison with others and how the parent will carry it. Pick one small act that fits.', '[{"id": "f0", "type": "textarea", "label": "What matters most this season"}, {"id": "f1", "type": "textarea", "label": "What can wait"}, {"id": "f2", "type": "textarea", "label": "The voice of comparison says"}, {"id": "f3", "type": "textarea", "label": "One small act that fits"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('self-soothe-between-feeds-kit', 'Self-Soothe Between Feeds Kit', 'dbt'::resource_kind, 'The parent builds a short soothe-with-senses plan for stolen moments.', 'Use it to help a parent find small, quick ways to settle.', array['Adults']::text[], '20 minutes', 'Choose one item per sense that takes a minute or less, such as a warm drink or a scent. Practice it in session. Keep it realistic to a tired day.', '[{"id": "f0", "type": "textarea", "label": "Something to see"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch or taste"}, {"id": "f3", "type": "textarea", "label": "When I will use my kit"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'distress tolerance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('night-shift-and-rest-planner-for-two', 'Night Shift and Rest Planner for Two', 'couples'::resource_kind, 'Partners plan who takes which stretches so each can rest.', 'Use it to help partners share the load of care and sleep.', array['Couples']::text[], '30 minutes', 'Lay out the week and plan protected rest for each partner. Talk about feelings of resentment kindly. Agree to adjust after a week. If either partner is struggling, a clinician check-in is the clinician''s call.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I most need rest"}, {"id": "f1", "type": "textarea", "label": "Partner B: when I most need rest"}, {"id": "f2", "type": "textarea", "label": "Our trial plan"}, {"id": "f3", "type": "textarea", "label": "How we will talk about it"}]'::jsonb, array['perinatal and postpartum', 'couples', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('proof-of-my-strengths-folder', 'Proof of My Strengths Folder', 'worksheet'::resource_kind, 'The client collects proof of strengths from real moments and what others have said.', 'Use it to help a client build a file of actual strengths.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for moments when the client used a strength and what others noticed. Add one per day. Review in session and have them read it aloud.', '[{"id": "f0", "type": "textarea", "label": "A strength I have"}, {"id": "f1", "type": "textarea", "label": "A moment I used it"}, {"id": "f2", "type": "textarea", "label": "What someone said"}, {"id": "f3", "type": "textarea", "label": "How I will use it next"}]'::jsonb, array['self-esteem', 'strengths', 'evidence']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('inner-critic-courtroom-page', 'Inner Critic Courtroom Page', 'cbt'::resource_kind, 'The client puts a critical thought on trial with evidence for and against.', 'Use it to help a client weigh critical thoughts like evidence.', array['Adults', 'Teens']::text[], '25 minutes', 'Let the client play prosecutor, defense and judge. Keep the evidence factual. The verdict is a balanced statement the client can say.', '[{"id": "f0", "type": "textarea", "label": "The critical thought"}, {"id": "f1", "type": "textarea", "label": "Evidence for it"}, {"id": "f2", "type": "textarea", "label": "Evidence against it"}, {"id": "f3", "type": "textarea", "label": "The verdict I can accept"}]'::jsonb, array['self-esteem', 'core beliefs', 'self-criticism']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('self-as-context-sky-exercise', 'Self as Context Sky Exercise', 'act'::resource_kind, 'The client pictures themselves as the sky holding passing weather of thoughts about worth.', 'Use it to help a client step back from thoughts about their value.', array['Adults', 'Teens']::text[], '20 minutes', 'Guide an image of sky and weather. Name a few self-judging thoughts as weather. Debrief on what is still there when the weather moves.', '[{"id": "f0", "type": "textarea", "label": "A judging thought I notice"}, {"id": "f1", "type": "textarea", "label": "What the sky image was like"}, {"id": "f2", "type": "textarea", "label": "What stays the same"}, {"id": "f3", "type": "textarea", "label": "Where I could use it"}]'::jsonb, array['self-esteem', 'self-as-context', 'defusion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('build-mastery-and-positive-moments-plan', 'Build Mastery and Positive Moments Plan', 'dbt'::resource_kind, 'The client plans one mastery activity and one pleasant event a day.', 'Use it to help a client build experiences that support a sense of worth.', array['Adults', 'Teens']::text[], 'One week', 'Pick activities that stretch gently and ones just for enjoyment. Plan them in the calendar. Review how it felt to finish them.', '[{"id": "f0", "type": "textarea", "label": "Mastery activity I planned"}, {"id": "f1", "type": "textarea", "label": "Pleasant event I planned"}, {"id": "f2", "type": "textarea", "label": "Did I do them"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}]'::jsonb, array['self-esteem', 'emotion regulation', 'routines']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('things-i-like-about-being-me-poster', 'Things I Like About Being Me Poster', 'kids'::resource_kind, 'The child makes a poster of what they like, do well and love about being themselves.', 'Use it to help a child notice and name their own strengths.', array['Children']::text[], '30 minutes', 'Supply paper, markers and photos if available. The child draws what they like and do well. Parent role: add true, specific praise and avoid comparing to others. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "Things I am good at"}, {"id": "f1", "type": "textarea", "label": "Things I like"}, {"id": "f2", "type": "textarea", "label": "What others like about me"}, {"id": "f3", "type": "textarea", "label": "What I want to try"}]'::jsonb, array['self-esteem', 'children', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('attention-inward-versus-outward-sheet', 'Attention Inward Versus Outward Sheet', 'worksheet'::resource_kind, 'The client notes where attention goes during social moments and tries shifting outward.', 'Use it to help a client notice how self-focus feels and try something else.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client rate self-focus after a social event, then plan to put attention on the other person or task next time. Compare the two experiences.', '[{"id": "f0", "type": "textarea", "label": "The social moment"}, {"id": "f1", "type": "textarea", "label": "Where my attention was"}, {"id": "f2", "type": "textarea", "label": "How I felt"}, {"id": "f3", "type": "textarea", "label": "Where I will try putting it"}, {"id": "f4", "type": "textarea", "label": "What changed"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('social-prediction-test-page', 'Social Prediction Test Page', 'cbt'::resource_kind, 'The client predicts what others will think, tests it and records results.', 'Use it to help a client check predictions about how others react.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a small social task. The client predicts what will happen and how sure they are, does it and compares. Choose the next test together.', '[{"id": "f0", "type": "textarea", "label": "My prediction"}, {"id": "f1", "type": "textarea", "label": "How sure I am (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('showing-up-anyway-values-plan', 'Showing Up Anyway Values Plan', 'act'::resource_kind, 'The client picks a social value and a small act of connection with nerves along.', 'Use it to help a client act on connection with nerves present.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what kind of friend or colleague they want to be. Choose a small step and name the nervous thoughts. Follow up on what it was like.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "A small social step"}, {"id": "f2", "type": "textarea", "label": "What my mind says"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['social anxiety', 'values', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('give-skill-conversation-practice', 'GIVE Skill Conversation Practice', 'dbt'::resource_kind, 'The client practices being gentle, interested, validating and easy in conversation.', 'Use it to help a client practice warm conversation steps.', array['Adults', 'Teens']::text[], '25 minutes', 'Teach each letter and role-play a short chat. Let the client pick one skill to try this week and report back.', '[{"id": "f0", "type": "textarea", "label": "The conversation I practiced"}, {"id": "f1", "type": "textarea", "label": "Which skill I used"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "What I will try"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'social skills', 'core DBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('awkward-moments-role-play-game', 'Awkward Moments Role-Play Game', 'game'::resource_kind, 'Players draw social scenario cards, act out a response and get supportive feedback.', 'Use it to help clients rehearse social moments with peers.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: draw a card, act it for one minute, receive one kind observation. Passing is fine. Debrief on what felt doable and what to try.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "What I did"}, {"id": "f2", "type": "textarea", "label": "What the group noticed"}, {"id": "f3", "type": "textarea", "label": "What I will try"}]'::jsonb, array['social anxiety', 'game', 'social skills']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('waves-of-grief-journal-page', 'Waves of Grief Journal Page', 'worksheet'::resource_kind, 'The client notes when grief comes in waves and what helps it pass.', 'Use it to help a client track the rhythm of grief and what supports them.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note triggers, intensity and what helped without judgment. Share that grief has no timetable. Review what comforted them most.', '[{"id": "f0", "type": "textarea", "label": "When a wave came"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What helped"}, {"id": "f3", "type": "textarea", "label": "What I need this week"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('unhelpful-guilt-thoughts-after-loss', 'Unhelpful Guilt Thoughts After Loss', 'cbt'::resource_kind, 'The client sorts guilt thoughts into reasonable regret and unfair self-blame.', 'Use it to help a client sort guilt more fairly after a loss.', array['Adults', 'Teens']::text[], '25 minutes', 'Listen first. Then sort guilt thoughts: what was in their control and what was not. Write a balanced thought together. Be gentle and unhurried.', '[{"id": "f0", "type": "textarea", "label": "A guilt thought"}, {"id": "f1", "type": "textarea", "label": "What I knew then"}, {"id": "f2", "type": "textarea", "label": "What was in my control"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}]'::jsonb, array['grief and loss', 'guilt', 'thought record']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('carrying-love-forward-values-page', 'Carrying Love Forward Values Page', 'act'::resource_kind, 'The client names what they loved about the person and an action that honors it.', 'Use it to help a client carry what mattered into daily life.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the person valued and what the client valued in them. Choose a small way to honor it. Make room for sadness alongside.', '[{"id": "f0", "type": "textarea", "label": "What I valued about them"}, {"id": "f1", "type": "textarea", "label": "What mattered to us"}, {"id": "f2", "type": "textarea", "label": "A small way to honor it"}, {"id": "f3", "type": "textarea", "label": "What I will make room for"}]'::jsonb, array['grief and loss', 'values', 'acceptance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('self-soothing-anniversary-plan', 'Self-Soothing Anniversary Plan', 'dbt'::resource_kind, 'The client plans a gentle way to care for themselves on hard dates.', 'Use it to help a client prepare for difficult days with comfort.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a date coming up and plan with the senses and support. Include a person to contact and a flexible plan. Check in afterward.', '[{"id": "f0", "type": "textarea", "label": "The date"}, {"id": "f1", "type": "textarea", "label": "What I will do for comfort"}, {"id": "f2", "type": "textarea", "label": "Who I will contact"}, {"id": "f3", "type": "textarea", "label": "What I will do if it is harder than planned"}]'::jsonb, array['grief and loss', 'self-soothing', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('keepsake-shoebox-for-missing-someone', 'Keepsake Shoebox for Missing Someone', 'kids'::resource_kind, 'The child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to help a child keep memories close in a safe way.', array['Children']::text[], '35 minutes', 'Provide a box and craft supplies. The child draws and chooses keepsakes, and may share stories. Parent role: listen, share a memory and avoid hurrying. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "Someone I miss"}, {"id": "f1", "type": "textarea", "label": "A good memory"}, {"id": "f2", "type": "textarea", "label": "What I put in my box"}, {"id": "f3", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('complaint-to-request-rewriter', 'Complaint to Request Rewriter', 'worksheet'::resource_kind, 'The client turns a complaint into a need and a specific request.', 'Use it to help a client ask clearly for what they need.', array['Adults']::text[], '20 minutes', 'Take a complaint and ask what need lies beneath. Rewrite as a specific, doable request. Role-play saying it once.', '[{"id": "f0", "type": "textarea", "label": "The complaint"}, {"id": "f1", "type": "textarea", "label": "The need underneath"}, {"id": "f2", "type": "textarea", "label": "My specific request"}, {"id": "f3", "type": "textarea", "label": "How I will say it"}]'::jsonb, array['relationship issues', 'communication', 'assertiveness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-page', 'Mind Reading Check Page', 'cbt'::resource_kind, 'The client notes an assumption about a partner or friend and tests it.', 'Use it to help a client check assumptions about what others think.', array['Adults', 'Teens']::text[], '25 minutes', 'Write the assumption, other possible explanations and a way to ask. Practice the question out loud. Report what the other person actually said.', '[{"id": "f0", "type": "textarea", "label": "What I assumed"}, {"id": "f1", "type": "textarea", "label": "Other explanations"}, {"id": "f2", "type": "textarea", "label": "How I could ask"}, {"id": "f3", "type": "textarea", "label": "What I found out"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('relationship-values-and-actions-sheet', 'Relationship Values and Actions Sheet', 'act'::resource_kind, 'The client names what kind of partner or friend they want to be and one action.', 'Use it to help a client act on relationship values.', array['Adults']::text[], '25 minutes', 'Ask what the client wants to stand for in relationships. Pick one action this week that fits it even if the other person does not change.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be"}, {"id": "f1", "type": "textarea", "label": "One action this week"}, {"id": "f2", "type": "textarea", "label": "What my mind says"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['relationship issues', 'values', 'committed action']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('dear-man-request-rehearsal-page', 'DEAR MAN Request Rehearsal Page', 'dbt'::resource_kind, 'The client drafts a request using describe, express, assert, reinforce and the other DEAR MAN steps.', 'Use it to help a client rehearse an assertive request.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through each letter with a real request. Rehearse once aloud with the clinician. The client decides when and whether to use it.', '[{"id": "f0", "type": "textarea", "label": "The request"}, {"id": "f1", "type": "textarea", "label": "Describe and express"}, {"id": "f2", "type": "textarea", "label": "Assert and reinforce"}, {"id": "f3", "type": "textarea", "label": "Stay mindful, appear confident, negotiate"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness', 'assertiveness']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('repair-attempt-role-play-cards', 'Repair Attempt Role-Play Cards', 'game'::resource_kind, 'Players draw a conflict card, practice a repair move and say how the other might respond.', 'Use it to help clients rehearse repairing after conflict.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Rules: draw a card, try one repair sentence, and the partner replies in turn. Pass if needed. Debrief on which repair moves felt natural.', '[{"id": "f0", "type": "textarea", "label": "The scenario"}, {"id": "f1", "type": "textarea", "label": "The repair I tried"}, {"id": "f2", "type": "textarea", "label": "How the reply felt"}, {"id": "f3", "type": "textarea", "label": "What I will use in real life"}]'::jsonb, array['relationship issues', 'game', 'repair', 'relationships']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('trusted-supports-and-boundaries-page', 'Trusted Supports and Boundaries Page', 'worksheet'::resource_kind, 'The client lists people who feel safe and what they want from each, at their own pace.', 'Use it to help a client name supports and set comfortable limits.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep to the present. The client lists trusted people and ways to let them know what helps. No details of past events are needed or written. Review limits they want to keep and how to state them.', '[{"id": "f0", "type": "textarea", "label": "People who feel safe to me"}, {"id": "f1", "type": "textarea", "label": "What I would like from each"}, {"id": "f2", "type": "textarea", "label": "Limits I want to keep"}, {"id": "f3", "type": "textarea", "label": "How I will say it"}]'::jsonb, array['sexual abuse', 'support', 'boundaries']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('today-s-self-blame-gentle-rewrite', 'Today''s Self-Blame Gentle Rewrite', 'cbt'::resource_kind, 'The client notices self-blaming thoughts in daily life and writes a kinder balanced one.', 'Use it to help a client ease self-blame without revisiting events.', array['Adults', 'Teens']::text[], '25 minutes', 'Work only with present thoughts and not the events. Have the client note the thought, how strongly they believe it and a kinder version. Pause to ground if distress rises. 988 (call or text) is available if the client is in crisis.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought I noticed"}, {"id": "f1", "type": "textarea", "label": "How much I believed it"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "A kinder thought"}]'::jsonb, array['sexual abuse', 'self-compassion', 'stabilizing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('reclaiming-my-choices-values-page', 'Reclaiming My Choices Values Page', 'act'::resource_kind, 'The client lists areas of life where they want more choice and one small step.', 'Use it to help a client rebuild a sense of choice and direction.', array['Adults', 'Teens']::text[], '25 minutes', 'Emphasize choice and pacing. The client names what matters and one small step they can decide to take or not. Never ask for details of what happened.', '[{"id": "f0", "type": "textarea", "label": "What matters to me"}, {"id": "f1", "type": "textarea", "label": "Where I want more choice"}, {"id": "f2", "type": "textarea", "label": "A small step I can decide on"}, {"id": "f3", "type": "textarea", "label": "What helps me feel steady"}]'::jsonb, array['sexual abuse', 'values', 'pacing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('safe-body-check-in-and-grounding-card', 'Safe Body Check-In and Grounding Card', 'dbt'::resource_kind, 'The client checks in with the body in a gentle way and picks a grounding step.', 'Use it to help a client reconnect with body sensations at a safe pace.', array['Adults', 'Teens']::text[], '20 minutes', 'Offer a choice of eyes open or closed. Scan only the parts that feel comfortable and skip any that do not. Pair with grounding. Stop if the client wants to.', '[{"id": "f0", "type": "textarea", "label": "What I notice in my body now"}, {"id": "f1", "type": "textarea", "label": "What feels steady"}, {"id": "f2", "type": "textarea", "label": "A grounding step I chose"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['sexual abuse', 'grounding', 'body awareness', 'stabilizing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('pacing-intimacy-and-trust-conversation-guide', 'Pacing Intimacy and Trust Conversation Guide', 'couples'::resource_kind, 'Partners talk about pace, consent signals and what feels safe in their relationship.', 'Use it to help partners agree on pacing and communication.', array['Couples']::text[], '35 minutes', 'Partners share what helps them feel safe and a way to say pause. Neither is asked to share past details. Agree on small steps and revisit.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel safe"}, {"id": "f1", "type": "textarea", "label": "Partner B: what helps me feel safe"}, {"id": "f2", "type": "textarea", "label": "Our pause signal"}, {"id": "f3", "type": "textarea", "label": "Small steps we agree on"}]'::jsonb, array['sexual abuse', 'couples', 'safety', 'pacing']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-by-situation-chart', 'Coping Toolbox by Situation Chart', 'worksheet'::resource_kind, 'The client matches skills to different kinds of hard moments.', 'Use it to help a client pick fitting skills for each kind of difficulty.', array['Adults', 'Teens']::text[], '25 minutes', 'List moments like waiting, arguments and sleeplessness and pick two skills for each. Practice one. Review what felt natural and revise.', '[{"id": "f0", "type": "textarea", "label": "Hard moments I face"}, {"id": "f1", "type": "textarea", "label": "Skills for each"}, {"id": "f2", "type": "textarea", "label": "The one I will practice"}, {"id": "f3", "type": "textarea", "label": "What I learned"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('pocket-statement-cards-that-ring-true', 'Pocket Statement Cards That Ring True', 'cbt'::resource_kind, 'The client writes short helpful statements on cards for tough moments.', 'Use it to help a client carry balanced thoughts in their pocket.', array['Adults', 'Teens']::text[], '20 minutes', 'Use thoughts the client believes, not slogans. Test each card by asking if it feels true. Have the client keep two cards handy.', '[{"id": "f0", "type": "textarea", "label": "A tough moment"}, {"id": "f1", "type": "textarea", "label": "What my mind says"}, {"id": "f2", "type": "textarea", "label": "A card that feels true"}, {"id": "f3", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('dropping-the-rope-practice', 'Dropping the Rope Practice', 'act'::resource_kind, 'The client imagines a tug of war with a struggle and what happens when they drop the rope.', 'Use it to help a client let go of a struggle and use their hands for something else.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through the tug of war metaphor and let the client name the struggle. Invite them to imagine putting the rope down and doing something valued with their hands.', '[{"id": "f0", "type": "textarea", "label": "The struggle I pull on"}, {"id": "f1", "type": "textarea", "label": "What it costs"}, {"id": "f2", "type": "textarea", "label": "What dropping the rope would look like"}, {"id": "f3", "type": "textarea", "label": "What I would do with my hands"}]'::jsonb, array['coping skills', 'acceptance', 'core ACT', 'metaphor']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('improve-steps-personal-picker', 'IMPROVE Steps Personal Picker', 'dbt'::resource_kind, 'The client builds a menu using imagery, meaning, prayer, relaxation, one thing, vacation and encouragement.', 'Use it to help a client improve a hard moment without making it worse.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through each item and let the client choose what fits. Keep it practical. Try one in session. Skip prayer if it does not fit their beliefs.', '[{"id": "f0", "type": "textarea", "label": "Items I like"}, {"id": "f1", "type": "textarea", "label": "One I tried"}, {"id": "f2", "type": "textarea", "label": "How it helped"}, {"id": "f3", "type": "textarea", "label": "Where I keep this menu"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('room-hunt-for-skill-reminders', 'Room Hunt for Skill Reminders', 'game'::resource_kind, 'Players hunt for items that remind them of a skill and explain how they would use it.', 'Use it to help clients link everyday objects to coping skills.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Rules: find a safe object for each skill in a set time, then explain it to the group in turn. No wrong answers. Debrief on which skills they will use.', '[{"id": "f0", "type": "textarea", "label": "The object I found"}, {"id": "f1", "type": "textarea", "label": "The skill it stands for"}, {"id": "f2", "type": "textarea", "label": "When I will use it"}, {"id": "f3", "type": "textarea", "label": "A skill I learned from others"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('step-by-step-fear-ranking-sheet', 'Step by Step Fear Ranking Sheet', 'worksheet'::resource_kind, 'The client ranks situations tied to a fear from easiest to hardest.', 'Use it to help a client build a graded list for gradual practice.', array['Adults', 'Teens']::text[], '25 minutes', 'List ten situations and rate each 0 to 100. Space them evenly. Pick a first step with the client that feels doable, and decide support.', '[{"id": "f0", "type": "textarea", "label": "The fear"}, {"id": "f1", "type": "textarea", "label": "Situations from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "Ratings"}, {"id": "f3", "type": "textarea", "label": "My first step"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('fear-facts-and-prediction-sheet', 'Fear Facts and Prediction Sheet', 'cbt'::resource_kind, 'The client writes what they fear will happen, checks facts and compares with real events.', 'Use it to help a client compare predictions with what happens.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write the prediction, gather factual information and test it with a planned step. Record the result and update the ladder.', '[{"id": "f0", "type": "textarea", "label": "What I fear will happen"}, {"id": "f1", "type": "textarea", "label": "Facts I looked up"}, {"id": "f2", "type": "textarea", "label": "What happened when I tried"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['phobias', 'behavioral experiment', 'evidence']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('fear-and-values-crossroads', 'Fear and Values Crossroads', 'act'::resource_kind, 'The client weighs what avoiding a feared situation protects and what it costs.', 'Use it to help a client choose between avoidance and what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a crossroads with avoidance on one path and values on the other. Notice the costs and gains of each. Choose a step toward values with fear allowed.', '[{"id": "f0", "type": "textarea", "label": "What I avoid"}, {"id": "f1", "type": "textarea", "label": "What avoiding costs me"}, {"id": "f2", "type": "textarea", "label": "What I want instead"}, {"id": "f3", "type": "textarea", "label": "One step I will take"}]'::jsonb, array['phobias', 'avoidance', 'values']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('relaxed-body-before-and-after-exposure-log', 'Relaxed Body Before and After Exposure Log', 'dbt'::resource_kind, 'The client logs body tension before and after practice with a calming skill.', 'Use it to help a client use a body skill around exposure practice.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach paced breathing or relaxation of muscle groups. Record tension before and after. Note that tension may rise first and settle over time.', '[{"id": "f0", "type": "textarea", "label": "Practice step"}, {"id": "f1", "type": "textarea", "label": "Body tension before (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "Skill I used"}, {"id": "f3", "type": "textarea", "label": "Tension after"}]'::jsonb, array['phobias', 'breathing', 'distress tolerance']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('fear-face-mask-and-brave-plan', 'Fear Face Mask and Brave Plan', 'kids'::resource_kind, 'The child makes a mask of the fear and builds a brave plan with small steps.', 'Use it to help a child face a fear in tiny, playful steps.', array['Children']::text[], '30 minutes', 'Provide paper plates and markers. The child makes the fear face, then draws three small brave steps. Parent role: cheer each step and avoid forcing. Report safety concerns as required.', '[{"id": "f0", "type": "textarea", "label": "What my fear looks like"}, {"id": "f1", "type": "textarea", "label": "Step one"}, {"id": "f2", "type": "textarea", "label": "Step two"}, {"id": "f3", "type": "textarea", "label": "Who cheers me on"}]'::jsonb, array['phobias', 'children', 'art']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('things-my-body-does-for-me-list', 'Things My Body Does For Me List', 'worksheet'::resource_kind, 'The client lists what their body lets them do and feel.', 'Use it to help a client focus on what the body does and not how it looks.', array['Adults', 'Teens']::text[], '20 minutes', 'Prompt with activities, senses and connection. Ask the client to add one each day. Redirect appearance talk toward function and experience.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do"}, {"id": "f1", "type": "textarea", "label": "Moments I felt at ease in my body"}, {"id": "f2", "type": "textarea", "label": "People I do this with"}, {"id": "f3", "type": "textarea", "label": "One I will do this week"}]'::jsonb, array['body image', 'strengths', 'gratitude']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('looks-thought-unhooking-record', 'Looks Thought Unhooking Record', 'cbt'::resource_kind, 'The client notes a thought about their appearance, how strongly they believe it and a balanced alternative.', 'Use it to help a client see thoughts about appearance as thoughts.', array['Adults', 'Teens']::text[], '25 minutes', 'Do not debate looks. Work on the thought, its effect and a balanced alternative focused on values and function. Notice avoidance such as skipping events.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The thought about my looks"}, {"id": "f2", "type": "textarea", "label": "What I did afterward"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}]'::jsonb, array['body image', 'thought record', 'self-criticism']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('body-kindness-values-page', 'Body Kindness Values Page', 'act'::resource_kind, 'The client picks a value and a caring act toward their body that fits it.', 'Use it to help a client act kindly toward their body.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what caring means to them and pick a small act like rest or a comfortable activity. Name the critical voice and carry it along.', '[{"id": "f0", "type": "textarea", "label": "What caring means to me"}, {"id": "f1", "type": "textarea", "label": "A kind act for my body"}, {"id": "f2", "type": "textarea", "label": "What the critical voice says"}, {"id": "f3", "type": "textarea", "label": "How it went"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('non-judging-describe-and-appreciate-practice', 'Non-Judging Describe and Appreciate Practice', 'dbt'::resource_kind, 'The client practices describing a part of their body in neutral words and noting what it does.', 'Use it to help a client practice non-judgmental description.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with a hand or foot and describe only what is observable. Note judging thoughts and let them pass. Stop when it stops helping.', '[{"id": "f0", "type": "textarea", "label": "What I described"}, {"id": "f1", "type": "textarea", "label": "Judging thoughts I noticed"}, {"id": "f2", "type": "textarea", "label": "What that part does for me"}, {"id": "f3", "type": "textarea", "label": "How I felt after"}]'::jsonb, array['body image', 'mindfulness', 'core DBT']::text[], '2026-10-19T15:00:00+00:00'::timestamptz),
  ('talking-kindly-about-bodies-together', 'Talking Kindly About Bodies Together', 'couples'::resource_kind, 'Partners agree on supportive words and topics for talking about bodies and intimacy.', 'Use it to help partners talk with care about how they feel in their bodies.', array['Couples']::text[], '30 minutes', 'Each partner shares what helps and what to avoid. Agree on words and topics to leave aside. Revisit after a few weeks and adjust.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps"}, {"id": "f1", "type": "textarea", "label": "Partner A: what to avoid"}, {"id": "f2", "type": "textarea", "label": "Partner B: what helps"}, {"id": "f3", "type": "textarea", "label": "Partner B: what to avoid"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-10-19T15:00:00+00:00'::timestamptz)
